@app.cell
def _(
    DENSITY_TABLE_TEXT,
    NOAA_F107_HIGH75,
    NOAA_F107_LOW75,
    NOAA_F107_PREDICTED,
    NOAA_PREDICTION_START,
    SOLAR_HISTORY_AP,
    SOLAR_HISTORY_F107,
    SOLAR_HISTORY_START,
    bisect,
    dt,
    math,
    np,
):
    TOOL_VERSION = "0.2.5"
    TOOL_SLUG = "molab-orbital-lifetime"

    MU = 3.986004418e14  # m^3/s^2
    R_MEAN_KM = 6371.0  # altitude reference, as in the siblings
    R_EQ_KM = 6378.137
    J2 = 1.08262668e-3
    OMEGA_EARTH = 7.2921159e-5  # rad/s
    SUN_RATE_DEG_DAY = 360.0 / 365.2422
    DAYS_PER_MONTH = 30.436875
    REENTRY_KM = 120.0  # table floor; the remaining descent is hours
    MAX_YEARS = 30.0

    # Body sizes per CubeSat Design Specification rev 14 and the 6U/12U
    # specifications (envelope, mm), masses typical rather than the CDS maxima.
    FORM_FACTORS = {
        "1U": (10.0, 10.0, 11.35, 1.3),
        "1.5U": (10.0, 10.0, 17.02, 2.0),
        "2U": (10.0, 10.0, 22.7, 2.6),
        "3U": (10.0, 10.0, 34.05, 4.0),
        "6U": (10.0, 22.63, 36.6, 8.0),
        "12U": (22.63, 22.63, 36.6, 16.0),
        "Custom": (10.0, 10.0, 10.0, 1.0),
    }
    ATTITUDES = {
        "Tumbling": "tumbling",
        "Minimum drag": "min",
        "Maximum drag": "max",
        "X face into the flow": "ram_x",
        "Y face into the flow": "ram_y",
        "Z face into the flow": "ram_z",
    }
    ATTITUDE_LABELS = {v: k for k, v in ATTITUDES.items()}
    SHAPES = ["panel", "cylinder"]

    # Solar cycle minima (month of the 13-month smoothed SSN minimum, SILSO).
    CYCLE_STARTS = {
        19: "1954-04",
        20: "1964-10",
        21: "1976-03",
        22: "1986-09",
        23: "1996-08",
        24: "2008-12",
        25: "2019-12",
    }
    ANALOG_CYCLES = [19, 20, 21, 22, 23, 24]
    CLIMATOLOGY_CYCLES = [20, 21, 22, 23, 24]  # complete within the F10.7 record
    F107_FLOOR = 65.0

    # --- density table ---------------------------------------------------
    def _parse_density(text):
        d = {}
        for line in text.strip().split("\n"):
            if line.startswith("#"):
                continue
            k, _, v = line.partition(" ")
            d[k] = np.array(v.split(), dtype=float)
        tab = d["LOG10RHO"].reshape(len(d["INC"]), len(d["ALT"]), len(d["F107"]), len(d["AP"]))
        return d["INC"], d["ALT"], d["F107"], d["AP"], tab

    DENS_INC, DENS_ALT, DENS_F107, DENS_AP, DENS_TAB = _parse_density(DENSITY_TABLE_TEXT)
    _ALT_LIST = DENS_ALT.tolist()
    _F_LIST = DENS_F107.tolist()
    _AP_LIST = DENS_AP.tolist()

    def _bracket(axis, x):
        """Index and fraction for linear interpolation, clamped to the axis."""
        if x <= axis[0]:
            return 0, 0.0
        if x >= axis[-1]:
            return len(axis) - 2, 1.0
        i = bisect.bisect_right(axis, x) - 1
        return i, (x - axis[i]) / (axis[i + 1] - axis[i])

    def density_slice(inc_deg):
        """The (alt, f107, ap) log-density table at one inclination."""
        inc = min(abs(inc_deg), 180.0 - abs(inc_deg))
        i, f = _bracket(DENS_INC.tolist(), inc)
        return ((1 - f) * DENS_TAB[i] + f * DENS_TAB[i + 1]).tolist()

    def rho_kg_m3(h_km, f107, ap, tab3):
        """Trilinear interpolation on log10 density; h above the 6371 km sphere."""
        ia, fa = _bracket(_ALT_LIST, h_km)
        jf, ff = _bracket(_F_LIST, f107)
        ka, fk = _bracket(_AP_LIST, ap)
        t0, t1 = tab3[ia], tab3[ia + 1]
        r00 = t0[jf][ka] * (1 - fk) + t0[jf][ka + 1] * fk
        r01 = t0[jf + 1][ka] * (1 - fk) + t0[jf + 1][ka + 1] * fk
        r10 = t1[jf][ka] * (1 - fk) + t1[jf][ka + 1] * fk
        r11 = t1[jf + 1][ka] * (1 - fk) + t1[jf + 1][ka + 1] * fk
        r0 = r00 * (1 - ff) + r01 * ff
        r1 = r10 * (1 - ff) + r11 * ff
        return 10.0 ** (r0 * (1 - fa) + r1 * fa)

    # --- solar record ----------------------------------------------------
    def month_index(d):
        """Fractional months since the first history month."""
        y0, m0 = (int(x) for x in SOLAR_HISTORY_START.split("-"))
        return (d.year - y0) * 12 + (d.month - m0) + (d.day - 1) / 30.4375

    def month_index_of_tag(tag):
        y, m = (int(x) for x in tag.split("-"))
        return month_index(dt.date(y, m, 1))

    def date_of_month_index(mi):
        y0, m0 = (int(x) for x in SOLAR_HISTORY_START.split("-"))
        total = y0 * 12 + (m0 - 1) + mi
        y = int(total // 12)
        m = int(total % 12) + 1
        day = min(28, 1 + int((total % 1) * 30.4375))
        return dt.date(y, m, day)

    HIST_F107 = np.array(SOLAR_HISTORY_F107.split(), dtype=float)
    HIST_AP = np.array(SOLAR_HISTORY_AP.split(), dtype=float)
    HIST_END_MI = float(len(HIST_F107) - 1)
    HIST_END_DATE = date_of_month_index(HIST_END_MI)

    def interp_series(arr, mi):
        if mi <= 0:
            return float(arr[0])
        if mi >= len(arr) - 1:
            return float(arr[-1])
        i = int(mi)
        f = mi - i
        return float(arr[i] * (1 - f) + arr[i + 1] * f)

    CYCLE_START_MI = {k: month_index_of_tag(v) for k, v in CYCLE_STARTS.items()}
    CYCLE_LENGTH_MO = {k: CYCLE_START_MI[k + 1] - CYCLE_START_MI[k] for k in range(19, 25)}

    def _climatology(nbins=50):
        f_bins = np.zeros(nbins)
        a_bins = np.zeros(nbins)
        n_bins = np.zeros(nbins)
        for k in CLIMATOLOGY_CYCLES:
            s, L = CYCLE_START_MI[k], CYCLE_LENGTH_MO[k]
            for mi in range(int(math.ceil(s)), int(s + L)):
                b = min(nbins - 1, int((mi - s) / L * nbins))
                f_bins[b] += HIST_F107[mi]
                a_bins[b] += HIST_AP[mi]
                n_bins[b] += 1
        return f_bins / np.maximum(n_bins, 1), a_bins / np.maximum(n_bins, 1)

    CLIM_F107, CLIM_AP = _climatology()
    CLIM_N = len(CLIM_F107)

    def climatology(arr, phase):
        x = (phase % 1.0) * CLIM_N - 0.5
        i = int(math.floor(x)) % CLIM_N
        f = x - math.floor(x)
        return float(arr[i] * (1 - f) + arr[(i + 1) % CLIM_N] * f)

    def _cycle_peak(k):
        s, L = CYCLE_START_MI[k], CYCLE_LENGTH_MO[k]
        seg = HIST_F107[max(0, int(s)) : int(s + L)]
        if len(seg) < 12:
            return float("nan")
        return float(np.convolve(seg, np.ones(12) / 12, mode="valid").max())

    CYCLE_PEAKS = {k: _cycle_peak(k) for k in ANALOG_CYCLES}
    CLIM_PEAK = float(np.convolve(CLIM_F107, np.ones(6) / 6, mode="same").max())
    K_HIGH = max(CYCLE_PEAKS.values()) / CLIM_PEAK
    K_LOW = min(CYCLE_PEAKS.values()) / CLIM_PEAK

    NOAA_START_MI = month_index_of_tag(NOAA_PREDICTION_START)
    NOAA_SERIES = {
        "nominal": np.array(NOAA_F107_PREDICTED.split(), dtype=float),
        "high": np.array(NOAA_F107_HIGH75.split(), dtype=float),
        "low": np.array(NOAA_F107_LOW75.split(), dtype=float),
    }

    # --- formatting ------------------------------------------------------
    def fmt_int(x):
        return f"{int(round(x)):,}".replace(",", "'")

    def fmt_num(x, nd=1):
        if x is None or (isinstance(x, float) and (math.isnan(x) or math.isinf(x))):
            return "–"
        s = f"{x:,.{nd}f}".replace(",", "'")
        return s

    def fmt_years(y):
        if y is None:
            return f"> {fmt_int(MAX_YEARS)} yr"
        if y < 1.0:
            return f"{fmt_int(y * 365.25)} d"
        return f"{fmt_num(y, 1)} yr"

    return (
        ANALOG_CYCLES,
        ATTITUDES,
        ATTITUDE_LABELS,
        CLIM_AP,
        CLIM_F107,
        CYCLE_LENGTH_MO,
        CYCLE_START_MI,
        DAYS_PER_MONTH,
        DENS_ALT,
        F107_FLOOR,
        FORM_FACTORS,
        HIST_AP,
        HIST_END_DATE,
        HIST_END_MI,
        HIST_F107,
        J2,
        K_HIGH,
        K_LOW,
        MAX_YEARS,
        MU,
        NOAA_SERIES,
        NOAA_START_MI,
        OMEGA_EARTH,
        REENTRY_KM,
        R_EQ_KM,
        R_MEAN_KM,
        SUN_RATE_DEG_DAY,
        TOOL_SLUG,
        TOOL_VERSION,
        climatology,
        date_of_month_index,
        density_slice,
        fmt_num,
        fmt_years,
        interp_series,
        month_index,
        month_index_of_tag,
        rho_kg_m3,
    )


