@app.cell
def _(mo):
    ui_profile = mo.ui.file(kind="button", filetypes=[".toml"], label="Load profile (.toml)")
    return (ui_profile,)


@app.cell
def _(dt, tomllib, ui_profile):
    _raw = ui_profile.contents() if ui_profile.contents() else None
    profile = {}
    profile_error = None
    profile_warnings = []
    profile_name = None
    if _raw:
        try:
            profile = tomllib.loads(_raw.decode("utf-8"))
            profile_name = ui_profile.name()
        except Exception as _e:
            profile_error = str(_e)

    def P(path, default):
        """Dotted lookup; a value that is not a number falls back and is reported."""
        node = profile
        for part in path.split("."):
            if not isinstance(node, dict) or part not in node:
                return default
            node = node[part]
        if isinstance(default, bool):
            if isinstance(node, bool):
                return node
            if isinstance(node, str):
                return node.strip().lower() in ("true", "1", "yes", "on")
            return default
        if isinstance(default, (int, float)):
            if isinstance(node, bool) or not isinstance(node, (int, float)):
                profile_warnings.append(f"`{path}` is not a number; default kept")
                return default
            return float(node) if isinstance(default, float) else node
        return node

    def PH(path):
        node = profile
        for part in path.split("."):
            if not isinstance(node, dict) or part not in node:
                return False
            node = node[part]
        return True

    def P_date(path, default):
        v = P(path, "")
        if isinstance(v, (dt.date, dt.datetime)):
            return v.date() if isinstance(v, dt.datetime) else v
        if isinstance(v, str) and len(v) >= 10:
            try:
                return dt.date.fromisoformat(v[:10])
            except ValueError:
                profile_warnings.append(f"`{path}` is not a date; default kept")
        return default

    _tool = profile.get("tool") if isinstance(profile.get("tool"), str) else None
    if _tool is None and profile:
        if "modes" in profile:
            _tool = "bac_link_budget"
        elif "sensor" in profile:
            _tool = "bac_optical_payload"
        elif "storage" in profile:
            _tool = "bac_power_budget"
        elif "spacecraft" in profile or "deployables" in profile:
            _tool = "bac_orbital_lifetime"
    profile_tool = _tool
    profile_deployables = profile.get("deployables") if isinstance(profile.get("deployables"), list) else None
    return (
        P,
        P_date,
        profile,
        profile_deployables,
        profile_error,
        profile_name,
        profile_tool,
        profile_warnings,
    )


@app.cell
def _(
    mo,
    profile,
    profile_error,
    profile_name,
    profile_tool,
    profile_warnings,
    ui_profile,
):
    if profile_error:
        _status = mo.callout(mo.md(f"The profile could not be read: {profile_error}"), kind="danger")
    elif not profile:
        _status = mo.md("No profile loaded; the defaults are the BAC demo mission's.")
    else:
        _lines = [f"Loaded **{profile_name}**"]
        if profile_tool == "bac_orbital_lifetime":
            _lines.append("written by this tool; every table was read.")
        elif profile_tool in ("bac_link_budget", "bac_optical_payload", "bac_power_budget"):
            _who = {
                "bac_link_budget": "link budget",
                "bac_optical_payload": "optical payload",
                "bac_power_budget": "power budget",
            }[profile_tool]
            _lines.append(
                f"written by the {_who} tool: the `[orbit]` table was taken (altitude, inclination, LTDN, epoch); everything else it carries was ignored and the spacecraft keeps this tool's defaults."
            )
        else:
            _lines.append("of unknown origin: only keys this tool understands were read.")
        if profile_warnings:
            _lines.append("Values that were not usable: " + "; ".join(profile_warnings) + ".")
        _status = mo.md(" ".join(_lines))
    mo.hstack([ui_profile, _status], justify="start", gap=1, wrap=True, align="center")
    return


@app.cell
def _(
    ATTITUDES,
    ATTITUDE_LABELS,
    FORM_FACTORS,
    P,
    P_date,
    dt,
    mo,
    pd,
    profile_deployables,
):
    def N(**kw):
        lo, hi = kw.get("start", -1e18), kw.get("stop", 1e18)
        v = min(max(kw["value"], lo), hi)
        if float(kw.get("step", 1)).is_integer():
            v = int(round(v))
        kw["value"] = v
        return mo.ui.number(**kw)

    def S(**kw):
        lo, hi = kw["start"], kw["stop"]
        v = min(max(kw["value"], lo), hi)
        if float(kw.get("step", 1)).is_integer():
            v = int(round(v))
        kw["value"] = v
        kw.setdefault("show_value", True)
        return mo.ui.slider(**kw)

    _ff = P("spacecraft.form_factor", "1.5U")
    if _ff not in FORM_FACTORS:
        _ff = "Custom"
    _x, _y, _z, _m = FORM_FACTORS[_ff]
    _att_m = ATTITUDE_LABELS.get(P("spacecraft.attitude_mission", "tumbling"), "Tumbling")
    _att_a = ATTITUDE_LABELS.get(P("spacecraft.attitude_after_mission", "tumbling"), "Tumbling")

    # Orbit
    ui_altitude = S(
        start=200, stop=1000, step=5, value=P("orbit.altitude_km", 500), label="Altitude (km)", include_input=True
    )
    ui_inclination = S(
        start=0, stop=180, step=0.1, value=P("orbit.inclination_deg", 97.4), label="Inclination (°)", include_input=True
    )
    ui_ltdn = S(start=0, stop=24, step=0.25, value=P("orbit.ltdn_hours", 10.5), label="LTDN (h, SSO only)")
    ui_epoch = mo.ui.date(value=P_date("orbit.epoch", dt.date(2027, 6, 1)), label="Launch / epoch")

    # Mission
    ui_mission_years = S(
        start=0.25, stop=10, step=0.25, value=P("mission.duration_years", 2.0), label="Mission duration (yr)"
    )
    ui_att_mission = mo.ui.dropdown(options=list(ATTITUDES), value=_att_m, label="Attitude during the mission")
    ui_att_after = mo.ui.dropdown(options=list(ATTITUDES), value=_att_a, label="Attitude after end of mission")

    # Spacecraft
    ui_form = mo.ui.dropdown(options=list(FORM_FACTORS), value=_ff, label="Form factor")
    ui_size_x = N(start=1, stop=100, step=0.01, value=P("spacecraft.size_x_cm", _x), label="X (cm, Custom only)")
    ui_size_y = N(start=1, stop=100, step=0.01, value=P("spacecraft.size_y_cm", _y), label="Y (cm, Custom only)")
    ui_size_z = N(start=1, stop=100, step=0.01, value=P("spacecraft.size_z_cm", _z), label="Z (cm, Custom only)")
    ui_mass = N(start=0.1, stop=100, step=0.01, value=P("spacecraft.mass_kg", _m), label="Mass (kg)")
    ui_cd = S(start=1.5, stop=3.0, step=0.05, value=P("spacecraft.drag_coefficient", 2.2), label="Drag coefficient Cd")

    # Solar
    ui_next_cycle = mo.ui.text(value=str(P("solar.next_cycle_start", "2030-07")), label="Next cycle minimum (YYYY-MM)")
    ui_const_f107 = S(
        start=65, stop=300, step=5, value=P("solar.constant_f107", 150), label="Constant scenario F10.7 (sfu)"
    )
    ui_const_ap = S(start=0, stop=100, step=1, value=P("solar.constant_ap", 15), label="Constant scenario Ap")
    ui_ap_override = S(
        start=0, stop=100, step=1, value=P("solar.ap_override", 0), label="Ap override (0 = record and climatology)"
    )
    ui_fetch_live = mo.ui.switch(value=P("solar.fetch_live", False), label="Fetch the NOAA prediction live")

    # Deployables
    _rows = []
    if profile_deployables:
        for _d in profile_deployables:
            if isinstance(_d, dict):
                _rows.append(
                    {
                        "Name": str(_d.get("name", "")),
                        "Shape": str(_d.get("shape", "panel")),
                        "Count": _d.get("count", 1),
                        "Width (cm)": _d.get("width_cm", 10.0),
                        "Length (cm)": _d.get("length_cm", 30.0),
                        "Flow angle (°)": _d.get("flow_angle_deg", 0),
                        "Deployed": _d.get("deployed", True),
                        "Deploy at end of mission": _d.get("deploy_at_end_of_mission", False),
                    }
                )
    if not _rows:
        _rows = [
            {
                "Name": "UHF tape antennas",
                "Shape": "cylinder",
                "Count": 4,
                "Width (cm)": 0.3,
                "Length (cm)": 17.0,
                "Flow angle (°)": 0,
                "Deployed": True,
                "Deploy at end of mission": False,
            }
        ]
    ui_deployables = mo.ui.data_editor(pd.DataFrame(_rows), label="Deployables")

    ui_sidebar = mo.ui.switch(value=False, label="Controls in a sidebar")
    return (
        ui_altitude,
        ui_ap_override,
        ui_att_after,
        ui_att_mission,
        ui_cd,
        ui_const_ap,
        ui_const_f107,
        ui_deployables,
        ui_epoch,
        ui_fetch_live,
        ui_form,
        ui_inclination,
        ui_ltdn,
        ui_mass,
        ui_mission_years,
        ui_next_cycle,
        ui_sidebar,
        ui_size_x,
        ui_size_y,
        ui_size_z,
    )


@app.cell
def _(
    mo,
    ui_altitude,
    ui_ap_override,
    ui_att_after,
    ui_att_mission,
    ui_cd,
    ui_const_ap,
    ui_const_f107,
    ui_deployables,
    ui_epoch,
    ui_fetch_live,
    ui_form,
    ui_inclination,
    ui_ltdn,
    ui_mass,
    ui_mission_years,
    ui_next_cycle,
    ui_size_x,
    ui_size_y,
    ui_size_z,
):
    _left = mo.vstack(
        [
            mo.md("### Orbit"),
            mo.md(
                "Circular orbit; altitude above the 6371 km mean radius, as in the siblings. The epoch sets where in the solar cycle the mission starts."
            ),
            ui_altitude,
            ui_inclination,
            ui_ltdn,
            ui_epoch,
            mo.md("### Mission"),
            mo.md(
                "The attitude switches at end of mission; a spacecraft that stops controlling itself usually tumbles."
            ),
            ui_mission_years,
            ui_att_mission,
            ui_att_after,
        ]
    )
    _right = mo.vstack(
        [
            mo.md("### Spacecraft"),
            mo.md("A preset sets the body size; the X, Y, Z fields count only with Custom. Z is the long axis."),
            ui_form,
            ui_mass,
            ui_cd,
            mo.accordion({"Custom body size": mo.vstack([ui_size_x, ui_size_y, ui_size_z])}),
            mo.md("### Solar Activity"),
            mo.md(
                "The NOAA prediction and the analog cycles drive the scenarios; these settings shape the constant case and the continuation past the forecast."
            ),
            mo.accordion(
                {
                    "Solar settings": mo.vstack(
                        [ui_next_cycle, ui_const_f107, ui_const_ap, ui_ap_override, ui_fetch_live]
                    )
                }
            ),
        ]
    )
    knobs_wide = mo.hstack([_left, _right], justify="start", gap=2, wrap=True, widths="equal")
    knobs_tall = mo.vstack([_left, _right])
    deployables_block = mo.vstack(
        [
            mo.md("### Deployables"),
            mo.md(
                "Panels and booms that add drag area. Flow angle applies to the fixed attitudes: 0 is face-on (a cylinder broadside), 90 edge-on. Tumbling averages a panel to half its area and a cylinder to π/4 of its broadside area. A row that deploys at end of mission (a drag sail, a boom) counts in the after-mission area only."
            ),
            ui_deployables,
        ]
    )
    return deployables_block, knobs_tall, knobs_wide


@app.cell
def _(knobs_tall, mo, ui_sidebar):
    mo.sidebar([knobs_tall]) if ui_sidebar.value else None
    return


@app.cell
def _(deployables_block, knobs_wide, mo, ui_sidebar):
    if ui_sidebar.value:
        _panel = mo.md("Controls are in the sidebar.")
    else:
        _panel = mo.vstack([mo.md("## Control Panel"), knobs_wide, deployables_block])
    mo.vstack([ui_sidebar, _panel])
    return


